CREATE TABLE `wedding_hall` (
  `id` int(11) NOT NULL,
  `name` varchar(255) DEFAULT NULL,
  `inn` int(11) NOT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `phone2` varchar(20) DEFAULT NULL,
  `address` varchar(500) DEFAULT NULL,
  `region_id` int(11) DEFAULT NULL,
  `district_id` int(11) DEFAULT NULL,
  `mahalla_id` bigint(20) DEFAULT NULL,
  `loc_lng` double DEFAULT NULL,
  `loc_lat` double DEFAULT NULL,
  `capacity` int(11) DEFAULT NULL,
  `price` decimal(12,2) DEFAULT NULL,
  `price_type` enum('per_seat','per_hall') DEFAULT 'per_hall',
  `image` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `work_status` enum('working','repair','closed','temporarily_closed') DEFAULT 'working',
  `register_id` int(11) DEFAULT NULL,
  `modify_id` int(11) DEFAULT NULL,
  `status` enum('active','disabled','deleted') DEFAULT 'active',
  `created` datetime DEFAULT current_timestamp(),
  `updated` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

